SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='ecf86e2e-63cb-5fad-a553-42fa370907af'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('a12031b0-9110-5bf9-8dca-0faa7ca7ef3a','b435fbe0-eaad-5bba-91de-74bfd186b654')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='ecf86e2e-63cb-5fad-a553-42fa370907af'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='ecf86e2e-63cb-5fad-a553-42fa370907af'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('a12031b0-9110-5bf9-8dca-0faa7ca7ef3a','b435fbe0-eaad-5bba-91de-74bfd186b654')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='ecf86e2e-63cb-5fad-a553-42fa370907af'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
