  AND q.subject_scope='CustomerProfile:'||c.id::text AND q.semantic_key='customer-controls-lease-revoke-app-recovery' AND q.fingerprint='53aeeebca56a6b5d70fd24c683d14a5c392c41fd794f2798db3f05f75751deeb'
  AND q.state='committed' AND q.source_revision=0 AND q.result_schema_id='SH-004.v1#/$defs/response' AND q.result_schema_version='1'
  AND q.result_body='{"contract":"SH-004.v1","requestId":"lease-revoke-app-recovery","status":"ok","value":{"customerProfileId":"ecf86e2e-63cb-5fad-a553-42fa370907af","userId":"2e434f49-8b15-5e8d-aba9-ae6759f43fee","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"a12031b0-9110-5bf9-8dca-0faa7ca7ef3a","semanticKey":"customer-controls-lease-revoke-app-recovery","fingerprint":"53aeeebca56a6b5d70fd24c683d14a5c392c41fd794f2798db3f05f75751deeb","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='c12df1dd-80e7-51ee-97c6-d2246f6f836c' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='2d10c941-632a-5ddf-b119-d7a0dc23d57d' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"ecf86e2e-63cb-5fad-a553-42fa370907af"},"prior":null,"committed":{"id":"ecf86e2e-63cb-5fad-a553-42fa370907af","userId":"2e434f49-8b15-5e8d-aba9-ae6759f43fee","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='ecf86e2e-63cb-5fad-a553-42fa370907af' AND c.user_id='2e434f49-8b15-5e8d-aba9-ae6759f43fee' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
  AND c.display_name IS NULL AND c.avatar_media_id IS NULL AND c.city IS NULL AND c.state IS NULL AND c.country IS NULL AND c.archived_at IS NULL
