   AND ((o.id='316e8fec-490c-5330-80e0-4c669b4cd6ec' AND o.ordinal=0 AND o.kind='event' AND o.name='customer.lifecycle_changed.v1'
    AND o.payload_schema_id='urn:workin-ants:types:v1#/$defs/EventPayload_customer_lifecycle_changed_v1' AND o.payload='{"eventName":"customer.lifecycle_changed.v1","customerProfileId":"ecf86e2e-63cb-5fad-a553-42fa370907af","userId":"2e434f49-8b15-5e8d-aba9-ae6759f43fee","lifecycleRevision":"0","safeState":"active"}'::jsonb)
    OR (o.id='4fb987b5-d5c7-500d-abd0-0cd168013c1d' AND o.ordinal=1 AND o.kind='command' AND o.name='assignDefaultFreeTrack.v1'
    AND o.payload_schema_id='urn:workinants:database-review:foundation-payloads:v1#/$defs/assignDefaultFreeTrackCustomerCommand' AND o.payload='{"sourceOwner":"customer_buyer_profile","userId":"2e434f49-8b15-5e8d-aba9-ae6759f43fee","track":"customer","customerProfileId":"ecf86e2e-63cb-5fad-a553-42fa370907af","sourceCreationRevision":"0","sourceCreationReceipt":"a12031b0-9110-5bf9-8dca-0faa7ca7ef3a","semanticKey":"customer_buyer_profile/ecf86e2e-63cb-5fad-a553-42fa370907af/default-free-enrollment/v1"}'::jsonb)))=2));
